  "ch8.why.badsig": "签名对不上：文件被改过",
  "ch8.why.untrusted": "签名者不在信任名单里",
  "ch8.why.unsigned": "没有签名",
  "ch8.why.dbxhash": "哈希在 dbx 里：被拉黑了",
  "ch8.why.dbxcert": "签名的证书在 dbx 里：整张被拉黑",
